package com.cpf.core.common.tenant;import com.cpf.core.api.tenant.CpfTenant;import java.util.Optional;/** 요청/작업 범위 tenant context. 비동기 전파 시 명시적으로 capture/restore해야 합니다. */public final class CpfTenantContext {private static final ThreadLocal<CpfTenant> LOCAL=new ThreadLocal<>();private CpfTenantContext(){}public static Optional<CpfTenant> current(){return Optional.ofNullable(LOCAL.get());}public static Scope open(CpfTenant tenant){CpfTenant previous=LOCAL.get();LOCAL.set(tenant);return ()->{if(previous==null)LOCAL.remove();else LOCAL.set(previous);};}public interface Scope extends AutoCloseable{@Override void close();}}